@startuml

class Customer {
  + address : string
  + vat_number : string
  + head_office_address : string
}

class Product {
  + name : string
  + stock_level : int
}

class Order {
  + order_date : date
  + paid_date : date
  + status : OrderStatus
}

class OrderLine {
  + quantity : int
}

class Invoice {
  + invoice_date : date
}

class Shipment {
  + status : ShipmentStatus
}

class Delivery {
  + status : DeliveryStatus
}

enum OrderStatus {
  Pending
  Paid
  PartiallyShipped
  FullyShipped
}

enum ShipmentStatus {
  Packed
  Shipped
  Received
}

enum DeliveryStatus {
  Missing
  Damaged
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Order "1" *-- "1..*" OrderLine : contains
OrderLine "*" -- "1" Product : refers to
Order "1" -- "0..*" Invoice : billed_by
Order "1" -- "0..*" Shipment : grouped_into
Shipment "1" -- "1..*" OrderLine : contains
Shipment "1" -- "0..1" Delivery : results_in
Delivery "1" -- "1..*" OrderLine : contains

@enduml

